mapper.select:
SELECT f.chat_failure_no, left(f.session_no::text, 8) AS session_key, f.message_no, f.reason, f.detail::text AS detail, f.reviewed, f.reviewed_by, f.reviewed_at, f.review_comment, f.review_comment_ciphertext, f.review_comment_key_id, f.review_comment_encryption_version, f.frst_reg_dt, s.scenario_no, sc.title AS scenario_title, s.current_node_no FROM tb_chat_failure f JOIN tb_chat_session s ON s.chat_session_no = f.session_no JOIN tb_scenario sc ON sc.scenario_no = s.scenario_no
f.reviewed = #{reviewed}
ORDER BY f.reviewed ASC, f.frst_reg_dt DESC, f.chat_failure_no DESC LIMIT #{limit}

mapper.insert:
INSERT INTO tb_chat_failure (
    session_no, message_no, reason, detail, reviewed, reviewed_by, reviewed_at,
    review_comment, review_comment_ciphertext, review_comment_key_id,
    review_comment_encryption_version
)
VALUES (
    #{sessionNo}::uuid, #{messageNo}, #{reason}, CAST(#{detail} AS jsonb),
    #{reviewed}, #{reviewedBy}, #{reviewedAt}, #{reviewComment},
    #{reviewCommentCiphertext}, #{reviewCommentKeyId}, #{reviewCommentEncryptionVersion}
)

mapper.update:
UPDATE tb_chat_failure
SET review_comment = #{reviewComment},
    review_comment_ciphertext = #{reviewCommentCiphertext},
    review_comment_key_id = #{reviewCommentKeyId},
    review_comment_encryption_version = #{reviewCommentEncryptionVersion}
WHERE chat_failure_no = #{id}
